export function createCommunityUI({e,api,ui,link,filesView,workflow}){
 const staff=()=>ui.actor().role!=='student',hidden=(n,v)=>'<input type="hidden" name="'+n+'" value="'+e(v??'')+'">';
 const input=(l,n,v='',attrs='')=>'<label class="vle-field">'+l+'<input name="'+n+'" value="'+e(v)+'" '+attrs+'></label>';
 const area=(l,n,v='',max=5000)=>'<label class="vle-field">'+l+'<textarea name="'+n+'" maxlength="'+max+'">'+e(v)+'</textarea></label>';
 const check=(n,l,v)=>'<label class="community-check"><input type="checkbox" name="'+n+'" '+(v?'checked':'')+'> '+l+'</label>';
 const button=(l,v,primary=false)=>'<button type="submit" name="intent" value="'+v+'" class="btn '+(primary?'primary':'')+'">'+l+'</button>';
 const uploads=()=>'<label class="vle-field">Evidence files · up to 3 × 1 MB<input type="file" name="uploads" multiple accept=".pdf,.txt,.csv,.png,.jpg,.jpeg,.webp,.docx,.xlsx,.pptx,.mp3,.wav,.mp4,.webm"></label><small>New files replace the attached evidence. Leave empty to keep existing files.</small>';
 const date=d=>new Date(d).toLocaleDateString('en-GB',{day:'numeric',month:'short'});
 const images=files=>(files||[]).filter(f=>f.mime?.startsWith('image/')).map(f=>'<img class="community-evidence" src="data:'+e(f.mime)+';base64,'+e(f.data)+'" alt="'+e(f.name)+'">').join('');
 const sourceView=s=>s?'<details class="vle-panel"><summary>Returned work · '+e(s.title)+' · '+s.mark+'/'+s.maximum+'</summary><p class="vle-prose">'+e(s.answer||'')+'</p><p class="vle-prose">'+e(s.feedback||'')+'</p>'+filesView(s.files)+'</details>':'';
 const card=p=>'<a class="community-card vle-panel" href="#/classroom?'+new URLSearchParams({view:'portfolio',item:p.id})+'"><span class="vle-status">'+e(p.status)+(p.shareWithFamily?' · Shared with family':'')+'</span><h3>'+e(p.title)+'</h3><p>'+e(p.className)+' · '+e(p.studentName)+'</p><small>'+e((p.tags||[]).join(' · '))+' · '+date(p.updatedAt)+'</small></a>';
 async function portfolio(params){const item=params.get('item');if(item&&item!=='new')return portfolioItem(item);const q=new URLSearchParams();for(const k of ['classId','status','archived'])if(params.get(k))q.set(k,params.get(k));const d=await api('portfolio?'+q);if(item==='new'){if(staff())throw Error('Students create their own portfolio entries.');return editor({revision:0,status:'draft',classId:params.get('classId')||d.classes[0]?.id},d.classes);}
  return '<div class="learning-section-title"><h2>'+ (staff()?'Student portfolios':'My portfolio')+'</h2>'+(!staff()?link('＋ Add evidence',{view:'portfolio',item:'new',...(params.get('classId')?{classId:params.get('classId')}:{})}):'')+'</div><p>'+(staff()?'Review student reflections and evidence. Family sharing requires your explicit approval.':'Collect work you are proud of, explain what you learned, and submit it to your teacher. Drafts are private.')+'</p><form id="community-filters" class="community-filters"><label>Class <select name="classId"><option value="">All classes</option>'+d.classes.map(c=>'<option value="'+e(c.id)+'" '+(params.get('classId')===c.id?'selected':'')+'>'+e(c.name)+'</option>').join('')+'</select></label><label>Status <select name="status">'+['','pending','approved','returned',...(!staff()?['draft']:[])].map(v=>'<option '+(params.get('status')===v?'selected':'')+' value="'+v+'">'+(v||'All statuses')+'</option>').join('')+'</select></label>'+check('archived','Show archived',params.get('archived')==='1')+'</form><p class="muted">'+d.entries.length+' entries</p><div class="community-grid">'+d.entries.map((p,i)=>(i===6?'</div><details class="vle-panel"><summary>Show remaining entries</summary><div class="community-grid">':'')+card(p)).join('')+'</div>'+(d.entries.length>6?'</details>':'')+(!d.entries.length?'<p class="learning-empty">No portfolio entries here yet.</p>':'');
 }
 async function editor(p,classes){const data=await api('portfolio-sources?classId='+encodeURIComponent(p.classId));return '<p>'+link('← Portfolio',{view:'portfolio'})+'</p><h2>'+e(p.id?'Edit portfolio entry':'Add to my portfolio')+'</h2><p class="vle-note">Your draft is private. Submitting sends it to your teacher for review. Editing an approved entry removes approval and family sharing until it is reviewed again.</p><form data-vle="portfolio-save" class="vle-panel">'+hidden('id',p.id)+hidden('expectedRevision',p.revision)+'<div class="vle-form-grid"><label class="vle-field">Class<select name="classId" required>'+classes.map(c=>'<option value="'+e(c.id)+'" '+(c.id===p.classId?'selected':'')+'>'+e(c.name)+'</option>').join('')+'</select></label>'+input('Title','title',p.title,'required maxlength="160"')+'</div>'+area('What did I learn? What would I improve?','reflection',p.reflection)+input('Skills or tags (separate with commas)','tags',(p.tags||[]).join(', '),'maxlength="500"')+'<label class="vle-field">Include returned work (optional)<select name="sourceAssignmentId"><option value="">No linked work</option>'+sourceOptions(data.sources,p.source?.id)+'</select></label>'+sourceView(p.source)+filesView(p.files)+images(p.files)+uploads()+'<p>'+workflow.saveStatus()+'</p><div class="vle-actions">'+button('Save draft','draft')+button('Submit for review','submit',true)+'</div></form>';}
 const sourceOptions=(sources,selected)=>sources.map(a=>'<option value="'+e(a.id)+'" '+(a.id===selected?'selected':'')+'>'+e(a.title)+' · '+a.mark+'/'+a.maximum+'</option>').join('');
 async function portfolioItem(id){const p=await api('portfolio-item?id='+encodeURIComponent(id));if(!staff()&&!p.archived)return '<p><span class="vle-status">'+e(p.status)+(p.shareWithFamily?' · Shared with family':'')+'</span></p>'+await editor(p,(await api('portfolio')).classes)+ (p.reviewNote?'<section class="vle-feedback"><strong>Teacher feedback · '+e(p.status)+'</strong><p>'+e(p.reviewNote)+'</p></section>':'')+'<button class="btn" type="button" data-portfolio-archive="'+e(p.id)+'" data-revision="'+p.revision+'" data-archived="true">Archive entry</button>';return '<p>'+link('← Portfolio',{view:'portfolio'})+'</p><div class="learning-section-title"><h2>'+e(p.title)+'</h2><span class="vle-status">'+e(p.status)+(p.shareWithFamily?' · Shared with family':'')+'</span></div><p>'+e((p.tags||[]).join(' · '))+'</p><article class="vle-panel"><h3>Student reflection · '+e(p.studentName||'')+'</h3><p class="vle-prose">'+e(p.reflection||'No written reflection.')+'</p>'+images(p.files)+filesView(p.files)+sourceView(p.source)+'</article>'+(staff()&&!p.archived?'<form class="vle-panel" data-vle="portfolio-review">'+hidden('id',p.id)+hidden('expectedRevision',p.revision)+area('Teacher feedback','feedback',p.reviewNote)+check('shareWithFamily','Share this approved entry with the linked family account',p.shareWithFamily)+'<div class="vle-actions">'+button('Return for changes','return')+button('Approve entry','approve',true)+'</div></form>':'')+'<button class="btn" type="button" data-portfolio-archive="'+e(p.id)+'" data-revision="'+p.revision+'" data-archived="'+!p.archived+'">'+(p.archived?'Restore entry':'Archive entry')+'</button>';}
 function topicForm(classId,t={}){return '<form data-vle="discussion-save">'+hidden('classId',classId)+hidden('id',t.id)+hidden('expectedRevision',t.revision||0)+input('Title','title',t.title,'required maxlength="160"')+area('Discussion question or prompt','prompt',t.prompt,8000)+uploads()+'<div class="community-policies">'+check('studentReplies','Allow student replies',t.studentReplies??true)+check('moderated','Teacher approves student replies before classmates can see them',t.moderated??true)+check('requireOwnReply','Students post an approved response before seeing classmates’ replies',t.requireOwnReply)+check('pinned','Pin this topic',t.pinned)+check('closed','Close student replies',t.closed)+'</div>'+button(t.id?'Save topic settings':'Create discussion','save',true)+'</form>';}
 async function discussions(classId,isStaff){const d=await api('discussions?classId='+encodeURIComponent(classId));return '<div class="learning-section-title"><h2>Class discussions</h2><small>'+d.topics.length+' topics</small></div>'+(isStaff?'<details class="vle-panel"><summary>＋ Start a discussion</summary>'+topicForm(classId)+'</details>':'')+d.topics.map(t=>'<article class="vle-panel"><h3>'+link((t.pinned?'📌 ':'')+t.title,{class:classId,discussion:t.id})+'</h3><small>'+t.replies+' visible replies · '+(t.closed?'Closed':t.moderated?'Teacher moderated':'Open replies')+(t.pending?' · '+t.pending+' awaiting approval':'')+'</small></article>').join('')+(!d.topics.length?'<p class="learning-empty">Your teacher has not started a discussion yet.</p>':'');}
 function replyForm(t,r={}){return '<form data-vle="discussion-reply">'+hidden('threadId',t.id)+hidden('threadRevision',t.revision)+hidden('id',r.id)+hidden('expectedRevision',r.revision||0)+area(r.id?'Edit my reply':'My reply','body',r.body,4000)+uploads()+'<div class="vle-actions">'+button('Save private draft','draft')+button(r.id?'Post updated reply':'Post reply','post',true)+'</div></form>';}
 async function discussion(params){const d=await api('discussion?id='+encodeURIComponent(params.get('discussion'))),t=d.topic,isStaff=staff(),canReply=isStaff||t.studentReplies&&!t.closed;return '<p>'+link('← Class discussions',{class:t.classId,tab:'discussions'})+'</p><div class="learning-section-title"><h2>'+e(t.title)+'</h2><span class="vle-status">'+(t.closed?'Closed':t.moderated?'Teacher moderated':'Open replies')+'</span></div><article class="vle-panel"><p class="vle-prose">'+e(t.prompt)+'</p>'+images(t.files)+filesView(t.files)+'</article>'+(isStaff?'<details class="vle-panel"><summary>Edit prompt & reply settings</summary>'+topicForm(t.classId,t)+'</details>':'')+(!d.canReadPeers?'<p class="vle-note">Write your own response first. Classmates’ replies appear after your teacher approves your response.</p>':'')+'<h3>Replies</h3>'+d.replies.map(r=>'<article class="vle-panel community-reply"><div class="learning-section-title"><strong>'+e(r.authorName)+(r.teacher?' · Teacher':'')+'</strong><span class="vle-status">'+e(r.status)+'</span></div><p class="vle-prose">'+e(r.body)+'</p>'+images(r.files)+filesView(r.files)+(r.reviewNote?'<p class="vle-feedback">Teacher note: '+e(r.reviewNote)+'</p>':'')+(r.own&&canReply?'<details><summary>Edit my reply</summary>'+replyForm(t,r)+'</details>':'')+(isStaff&&!r.own&&r.status!=='draft'?'<details '+(r.status==='pending'?'open':'')+'><summary>Review reply</summary><form data-vle="discussion-moderate">'+hidden('id',r.id)+hidden('expectedRevision',r.revision)+area('Private note to this student','feedback',r.reviewNote,1000)+'<div class="vle-actions">'+button('Return for changes','return')+button('Approve reply','approve',true)+'</div></form></details>':'')+'</article>').join('')+(!d.replies.length?'<p class="learning-empty">No visible replies yet.</p>':'')+(canReply?'<section class="vle-panel"><h3>Add a reply</h3>'+(t.moderated&&!isStaff?'<p>Your reply is private until your teacher approves it.</p>':'')+replyForm(t)+'</section>':'<p class="vle-note">Student replies are closed. You can still read published responses.</p>');}
 function readAction(action,d,f,intent){if(action==='portfolio-save')d.status=intent==='submit'?'pending':'draft';if(action==='portfolio-review'||action==='discussion-moderate')d.decision=intent;if(action==='portfolio-review')d.shareWithFamily=f.elements.shareWithFamily.checked;if(action==='discussion-save')for(const k of ['studentReplies','moderated','requireOwnReply','pinned','closed'])d[k]=f.elements[k].checked;if(action==='discussion-reply'){d.draft=intent==='draft';d.threadRevision=Number(d.threadRevision);}}
 function bind(root){root.querySelector('#community-filters')?.addEventListener('change',ev=>{const data=Object.fromEntries(new FormData(ev.currentTarget));if(data.archived)data.archived='1';location.hash='/classroom?'+new URLSearchParams({view:'portfolio',...data});});root.querySelector('form[data-vle="portfolio-save"] [name="classId"]')?.addEventListener('change',async ev=>{const f=ev.target.form;try{const d=await api('portfolio-sources?classId='+encodeURIComponent(ev.target.value));if(f.isConnected)f.elements.sourceAssignmentId.innerHTML='<option value="">No linked work</option>'+sourceOptions(d.sources,'');}catch(error){ui.toast(error.message);}});root.querySelector('[data-portfolio-archive]')?.addEventListener('click',async ev=>{const b=ev.currentTarget;b.disabled=true;try{await api('portfolio-archive',{id:b.dataset.portfolioArchive,expectedRevision:Number(b.dataset.revision),archived:b.dataset.archived==='true'});ui.dirty(false);ui.render();}catch(error){ui.toast(error.message);b.disabled=false;}});}
 return{portfolio,discussions,discussion,readAction,bind};
}
